def _mapping_catalog(rows, source):
    tables={}
    for row in rows:
        table=row['table'];column=row['column']
        item=tables.setdefault(table,{'name':table,'fields':[],'source':source})
        precision=row.get('precision');scale=row.get('scale');length=row.get('length')
        kind=row['type']
        if kind in ('VARCHAR2','CHAR','NVARCHAR2') and length:kind=f'{kind}({length})'
        elif kind=='NUMBER' and precision is not None:
            kind=f"NUMBER({precision}{','+str(scale) if scale is not None else ''})"
        generated=column==table+'ID'
        item['fields'].append(dict(name=column,type=kind,required=row.get('nullable')=='N' and not generated,
            generated=generated,ordinal=row.get('ordinal',len(item['fields'])+1)))
    return list(tables.values())

def mapping_catalog(conn):
    """Discover ORDMAS and tables that reference it from the connected owner."""
    c=conn.cursor()
    c.execute('''select c.table_name,c.column_name,c.data_type,c.data_length,c.data_precision,c.data_scale,c.nullable,c.column_id
        from all_tab_columns c
        where c.owner=:owner and c.table_name in (
          select table_name from all_tab_columns
          where owner=:owner and (table_name='ORDMAS' or column_name='ORDMASID')
        ) order by case when c.table_name='ORDMAS' then 0 else 1 end,c.table_name,c.column_id''',owner=OWNER)
    rows=[dict(table=t,column=col,type=kind,length=length,precision=precision,scale=scale,
        nullable=nullable,ordinal=ordinal) for t,col,kind,length,precision,scale,nullable,ordinal in c]
    if not rows:raise ValueError('No ORDMAS-related tables were found in the Oracle owner.')
    return _mapping_catalog(rows,'oracle-live')

