def test_correction_cannot_replace_cell_provenance():
    original=workbooks.base_order();original['lines']=[dict(label='x',color='Blue',declared_total=5,
        sizes=[dict(size='M',quantity=5,source={'cell':'A1','value':5})])]
    local_store.identify([original]);edited=deepcopy(original)
    edited['lines'][0]['sizes'][0]['quantity']=7
    edited['lines'][0]['sizes'][0]['source']={'cell':'ZZ99','value':7}
    result=local_store.edited_orders([original],[edited])[0]
    assert result['lines'][0]['sizes'][0]['source']=={'cell':'A1','value':5}
    assert result['lines'][0]['declared_total'] is None
    assert result['lines'][0]['original_total']==5

def test_unedited_total_cannot_be_waived():
    original=workbooks.base_order();original['lines']=[dict(label='x',color='Blue',declared_total=9,
        sizes=[dict(size='M',quantity=5,source={})])]
    local_store.identify([original]);edited=deepcopy(original);edited['lines'][0]['declared_total']=None
    assert local_store.edited_orders([original],[edited])[0]['lines'][0]['declared_total']==9

def test_target_mapping_uses_server_owned_cell_value():
    order=workbooks.base_order();order.update(style='N44441',buyer='NEXT')
    order['provenance']={'style':{'sheet':'Merch','cell':'C4','value':'N44441'},'buyer':{'sheet':'Merch','cell':'C2','value':'NEXT'}}
    draft={'orders':[order],'sheets':[{'name':'Merch','cells':[
        {'cell':'C2','row':2,'col':3,'value':'NEXT'}, {'cell':'C4','row':4,'col':3,'value':'N44441'}]}]}
    catalog=[{'name':'ORDMAS','source':'test-catalog','fields':[
        {'name':'DOCID','type':'VARCHAR2(30)','required':True},
        {'name':'BUYER','type':'NUMBER(16)','required':True},
        {'name':'STYLENO','type':'NUMBER(16)','required':True}]}]
    automatic=workbooks.table_mapping(draft,'ORDMAS',catalog,sheet_name='Merch')
    assert automatic['preview']['STYLENO']=='N44441'
    manual=workbooks.table_mapping(draft,'ORDMAS',catalog,[{'target':'DOCID','sheet':'Merch','cell':'C4','value':'spoofed'}])
    assert manual['preview']['DOCID']=='N44441'
    workbooks.apply_table_mapping(draft,manual)
    assert draft['orders'][0]['order_ref']=='N44441'
    assert draft['orders'][0]['provenance']['order_ref']['cell']=='C4'

def test_excel_inspection_is_json_serializable_with_cell_addresses():
    workbook=Workbook();sheet=workbook.active;sheet.title='Orders';sheet['A1']='Style';sheet['B2']='0008'
    payload=BytesIO();workbook.save(payload)
    parsed=workbooks.parse(payload.getvalue())
    cell=next(c for c in parsed['sheets'][0]['cells'] if c['cell']=='B2')
    assert cell['value']=='0008'
    assert {'cell','row','col','value','formula','hidden','error'} <= cell.keys()

